#include "coh_entity_frame.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static uint64_t checks,cuts,mutations,successes;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"frame check failed %d: %s\n",__LINE__,#x);exit(1);}}while(0)
typedef struct{const uint8_t*data;size_t bytes,start,bits,header_end,list_end,control_end,end;unsigned mode,legacy,variant,list_scenario,control_scenario;}Fixture;
#include "fixtures.h"
static CohEntityFrame*out,*prior;static CohEntityFrameWorkspace*workspace;static CohEntityFrameFailure failure;
static CohRepSchema schema={{{11,1},{12,4},{13,10}},3,0};static uint32_t indices[]={4,7,9,10239};
static CohRepReader reader(const Fixture*f,const uint8_t*data,size_t bytes,size_t bits){CohRepReader r;CHECK(coh_rep_reader_bounded(&r,(CohBytes){data,bytes},bits,(int)f->mode,COH_REP_BOUNDED_MESSAGE_MAX)==COH_OK);r.cursor=f->start;return r;}
static CohEntityFrameContext context(const Fixture*f){CohEntityFrameContext c={4242,10,7,7,f->legacy,UINT64_C(0x12345678)};return c;}
static CohStatus parse(CohRepReader*r,const CohEntityFrameContext*c,size_t budget,size_t retained){CohRepReader before=*r;memset(out,0xa5,sizeof(*out));*prior=*out;CohStatus s=coh_entity_frame_read(r,c,&schema,indices,4,out,workspace,&failure,budget,retained);if(s!=COH_OK)CHECK(!memcmp(&before,r,sizeof(*r))&&!memcmp(out,prior,sizeof(*out)));return s;}
int main(void){out=malloc(sizeof(*out));prior=malloc(sizeof(*prior));workspace=malloc(sizeof(*workspace));CHECK(out&&prior&&workspace);
 for(size_t i=0;i<sizeof(fixtures)/sizeof(fixtures[0]);i++){
  const Fixture*f=&fixtures[i];CohEntityFrameContext c=context(f);CohRepReader r=reader(f,f->data,f->bytes,f->bits);CohStatus s=parse(&r,&c,COH_ENTITY_FRAME_RAM_MAX,0);
  if(f->variant==0){CHECK(s==COH_OK);CHECK(r.cursor==f->end&&out->end_bit==f->end&&out->begin_bit==f->start&&out->header_end_bit==f->header_end&&out->list_end_bit==f->list_end&&out->control_end_bit==f->control_end);CHECK(out->packet.data==f->data&&out->packet.size==f->bytes&&out->packet_bits==f->bits&&out->packet_lease_token==c.packet_lease_token);CHECK(out->header.command==COH_REP_ALLENTS&&out->header.full_update_id==77&&out->header.odd_send==1&&out->header.command_count==3&&out->header.has_debug_info==0);CHECK(out->selected_wire_identity_matched==1&&out->list.self_index==4&&out->list.self_dbid==4242&&out->list.self_entity_id==91);CHECK(out->selected.index==4&&out->selected.present&&out->selected.identity.is_self&&out->selected.identity.dbid==4242&&out->selected.identity.entity_id==91&&out->selected.create_packet==10&&out->selected.delete_packet==10);CHECK(out->selected.position.valid&&out->selected.position.position.x==12.5f&&out->selected.position.position.y==-6.25f&&out->selected.position.position.z==128.f);CHECK(out->control.has_server==1&&out->control.push_count==(f->control_scenario==2?32u:f->control_scenario==4?0u:f->control_scenario==7?1u:3u));CHECK(!!(out->control.server.flags&COH_CONTROL_STUN)==(f->control_scenario==4));CHECK(out->control.has_forced==(f->control_scenario==4?0u:1u));CHECK(out->deletes.count==2&&out->deletes.entries[0].index==4&&out->deletes.entries[1].index==7);CHECK(!out->complete_initial_update&&!out->actor_publication&&!out->ack_permitted&&!out->transport_end_verified&&!out->dictionary_authority&&!out->character_suffix_validated);successes++;
   for(size_t bit=f->start;bit<f->end;bit+=17){r=reader(f,f->data,f->bytes,bit);CHECK(parse(&r,&c,COH_ENTITY_FRAME_RAM_MAX,0)!=COH_OK);cuts++;}
   size_t minimum=sizeof(r)+sizeof(c)+sizeof(schema)+sizeof(indices)+sizeof(*out)+sizeof(*workspace)+sizeof(failure)+COH_ENTITY_FRAME_STACK_RESERVE+f->bytes;r=reader(f,f->data,f->bytes,f->bits);CHECK(parse(&r,&c,minimum,0)==COH_OK);r=reader(f,f->data,f->bytes,f->bits);CHECK(parse(&r,&c,minimum-1,0)==COH_LIMIT);r=reader(f,f->data,f->bytes,f->bits);CHECK(parse(&r,&c,minimum,1)==COH_LIMIT);
   c.selected_dbid++;r=reader(f,f->data,f->bytes,f->bits);CHECK(parse(&r,&c,COH_ENTITY_FRAME_RAM_MAX,0)!=COH_OK);c=context(f);c.schema_generation++;r=reader(f,f->data,f->bytes,f->bits);CHECK(parse(&r,&c,COH_ENTITY_FRAME_RAM_MAX,0)==COH_INVALID);c=context(f);
   CohRepSchema bad=schema;bad.entries[1].id=bad.entries[0].id;r=reader(f,f->data,f->bytes,f->bits);CohRepReader before=r;memset(out,0xa5,sizeof(*out));*prior=*out;CHECK(coh_entity_frame_read(&r,&c,&bad,indices,4,out,workspace,&failure,COH_ENTITY_FRAME_RAM_MAX,0)==COH_INVALID);CHECK(!memcmp(&r,&before,sizeof(r))&&!memcmp(out,prior,sizeof(*out)));r=before;CHECK(coh_entity_frame_read(&r,&c,&schema,indices,4,out,(CohEntityFrameWorkspace*)out,&failure,COH_ENTITY_FRAME_RAM_MAX,0)==COH_INVALID);CHECK(!memcmp(&r,&before,sizeof(r))&&!memcmp(out,prior,sizeof(*out)));
   if(i==0){r=reader(f,f->data,f->bytes,f->bits);CohRepReader b=r;memset(out,0xa5,sizeof(*out));*prior=*out;CHECK(coh_entity_frame_read(&r,&c,&schema,indices,1,out,workspace,&failure,COH_ENTITY_FRAME_RAM_MAX,0)==COH_NOT_FOUND);CHECK(!memcmp(&r,&b,sizeof(r))&&!memcmp(out,prior,sizeof(*out)));uint32_t duplicate[]={4,4};CHECK(coh_entity_frame_read(&r,&c,&schema,duplicate,2,out,workspace,&failure,COH_ENTITY_FRAME_RAM_MAX,0)==COH_INVALID);CHECK(!memcmp(&r,&b,sizeof(r))&&!memcmp(out,prior,sizeof(*out)));}
   uint8_t*d=malloc(f->bytes);CHECK(d);for(size_t byte=0;byte<f->bytes;byte+=3){memcpy(d,f->data,f->bytes);d[byte]^=255;r=reader(f,d,f->bytes,f->bits);s=parse(&r,&c,COH_ENTITY_FRAME_RAM_MAX,0);if(s==COH_OK)CHECK(r.cursor<=r.bits&&!out->actor_publication&&!out->ack_permitted);mutations++;}free(d);
  }else{CHECK(s!=COH_OK);if(f->variant==5)CHECK(s==COH_UNSUPPORTED&&failure.stage==COH_FRAME_HEADER);if(f->variant==6)CHECK(s==COH_INVALID&&failure.stage==COH_FRAME_HEADER);if(f->variant==7)CHECK(s==COH_UNSUPPORTED&&failure.stage==COH_FRAME_HEADER);}
 }
 printf("{\"passed\":true,\"checks\":%llu,\"source_component_compositions\":%zu,\"supported_preludes\":%llu,\"sampled_truncations\":%llu,\"sampled_mutations\":%llu,\"output_bytes\":%zu,\"workspace_bytes\":%zu,\"whole_initial_update_complete\":false,\"actor_publication\":false,\"ack_permitted\":false}\n",(unsigned long long)checks,sizeof(fixtures)/sizeof(fixtures[0]),(unsigned long long)successes,(unsigned long long)cuts,(unsigned long long)mutations,sizeof(*out),sizeof(*workspace));free(out);free(prior);free(workspace);return 0;
}
